def first_even(values):
    return next((x for x in values if x % 2 == 0), None)

assert first_even([]) is None
assert first_even([1, 3]) is None
assert first_even([3, 4, 2]) == 4

def normalize_tags(tags):
    result, seen = [], set()
    for raw in tags:
        tag = raw.strip()
        if tag and tag not in seen:
            seen.add(tag)
            result.append(tag)
    return result
